import React, { useState } from 'react';
import { Data } from './data';
import './internships.css';

export function Internships() {
  const [expandedCard, setExpandedCard] = useState(null);

  return (
    <section className="internships section" style={{display: 'grid',
    placeItems: 'center'}}id='internships'>
      <h2 className="section__title">Internships</h2>
      <span className="section__subtitle">My work experience</span><br></br>
      <div className="internships__container container grid">

          {Data.map((item) => (
            <div className={`flip-card${expandedCard === item.title ? ' is-flipped' : ''}`} key={item.title}>
            <div className="flip-card-inner" >
              <div className="flip-card-front">
                <h5>{item.title}</h5>
                <h6>{item.description}</h6>
                <h6>{item.role}</h6>
                <i className='uil uil-graduation-cap'></i>
                <button type="button" className="internships__details-button" aria-expanded={expandedCard === item.title} onClick={() => setExpandedCard(expandedCard === item.title ? null : item.title)}>
                  More details
                </button>
              </div><br></br>
              <div className="flip-card-back">
                <p>{item.details}</p>
                <button type="button" className="internships__details-button" onClick={() => setExpandedCard(null)}>
                  Back to summary
                </button>
              </div>
            </div>
            </div>
          ))}

      </div>


    </section>


  );
}
